import pathlib,json,datetime as dt,uuid,os,boto3
os.umask(0o077)
p=pathlib.Path(__file__).parent;config=json.loads((p/'bootstrap.json').read_text()); prep=json.loads((p/'prepared/preparation.json').read_text());window=json.loads((p/'launch-window.json').read_text());assert prep['budgetStop']==window['initialBudgetStop']; assert dt.datetime.now(dt.timezone.utc)<dt.datetime.fromisoformat(config['commissioningStop'].replace('Z','+00:00'))-dt.timedelta(minutes=20)
s=boto3.Session(profile_name='message-board-deploy');e=s.client('ec2',region_name='us-east-1');live=e.describe_instances(Filters=[{'Name':'instance-state-name','Values':['pending','running','stopping','stopped']}]);assert not any(i['InstanceType']=='m7a.4xlarge' for x in live['Reservations'] for i in x['Instances']), 'Existing core: reconcile, never overlap'
(p/'no-overlap.json').write_text(json.dumps(live,default=str));intent=p/'launch-intent.json';intent.open('x').write(json.dumps({'deadline':config['budgetStop'],'at':dt.datetime.now(dt.timezone.utc).isoformat(),'token':str(uuid.uuid4())}));token=json.loads(intent.read_text())['token']
l=json.loads((p/'launch-template.template.json').read_text());l['UserData']=(p/'prepared/initial-userdata.b64').read_text();l['NetworkInterfaces'][0]['PrivateIpAddress']=config['queryHost']['privateAddress']
for spec in l['TagSpecifications']:
 for tag in spec['Tags']:
  if tag['Key']=='ShutdownAt':tag['Value']=config['budgetStop']
(p/'launch-template-data.json').write_text(json.dumps(l));t=e.create_launch_template(ClientToken=token,LaunchTemplateName='rolling-restore-20261020-'+token[:8],LaunchTemplateData=l);(p/'launch-template-result.json').write_text(json.dumps(t,default=str));tid=t['LaunchTemplate']['LaunchTemplateId']
f=json.loads((p/'create-fleet.template.json').read_text());f['ClientToken']=token;f['ValidUntil']=config['budgetStop'];f['LaunchTemplateConfigs'][0]['LaunchTemplateSpecification']={'LaunchTemplateId':tid,'Version':'1'};(p/'create-fleet.intent.json').write_text(json.dumps(f));r=e.create_fleet(**f);(p/'create-fleet.result.json').write_text(json.dumps(r,default=str));print('Fleet created',r.get('FleetId'),'instances',r.get('Instances'),'errors',r.get('Errors'),flush=True)
fleet=e.describe_fleets(FleetIds=[r['FleetId']])['Fleets'][0];assert fleet['TerminateInstancesWithExpiration'] is True and fleet['ValidUntil']==dt.datetime.fromisoformat(config['budgetStop'].replace('Z','+00:00'));(p/'fleet-expiry-readback.json').write_text(json.dumps(fleet,default=str));print('Independent cloud deadline verified',config['budgetStop'],flush=True)
